sampling-distribution.solution:
r"""Reference solution for ST-12 Sampling Distributions and Standard Error.

A single seeded generator produces every draw, so the whole simulation is reproducible and
uses only `random()`, whose output Python guarantees across versions. The standard error uses the
unbiased $n-1$ variance, and the interval combines it with the exact 97.5% normal quantile.
"""
import math
import random
from statistics import NormalDist


def sample_means(population, n, reps, seed):
    rng = random.Random(seed)
    size = len(population)
    means = []
    for _ in range(reps):
        total = 0
        for _ in range(n):
            total += population[int(rng.random() * size)]
        means.append(total / n)
    return means


def standard_error(sample):
    n = len(sample)
    if n < 2:
        raise ValueError("need at least two values")
    m = sum(sample) / n
    var = sum((x - m) ** 2 for x in sample) / (n - 1)
    return math.sqrt(var) / math.sqrt(n)


def mean_ci95(sample):
    m = sum(sample) / len(sample)
    se = standard_error(sample)
    z = NormalDist().inv_cdf(0.975)
    return (m - z * se, m + z * se)

bootstrap-ci.solution:
r"""Reference solution for ST-13 Bootstrap Confidence Interval.

Each bootstrap replicate resamples n values with replacement using the documented index recipe
and records the statistic. Sorting the replicates and reading off the α/2 and 1−α/2 percentiles
gives the percentile interval.
"""
import math
import random


def _percentile(s_sorted, q):
    r = q / 100 * (len(s_sorted) - 1)
    i = math.floor(r)
    f = r - i
    if i + 1 < len(s_sorted):
        return s_sorted[i] + f * (s_sorted[i + 1] - s_sorted[i])
    return float(s_sorted[i])


def bootstrap_ci(data, n_boot=2000, alpha=0.05, seed=0, stat=None):
    if not data:
        raise ValueError("empty data")
    if n_boot < 1:
        raise ValueError("n_boot must be >= 1")
    if not 0 < alpha < 1:
        raise ValueError("alpha must be in (0, 1)")
    if stat is None:
        stat = lambda xs: sum(xs) / len(xs)
    rng = random.Random(seed)
    n = len(data)
    boots = []
    for _ in range(n_boot):
        sample = [data[int(rng.random() * n)] for _ in range(n)]
        boots.append(stat(sample))
    boots.sort()
    return float(_percentile(boots, 100 * alpha / 2)), float(_percentile(boots, 100 * (1 - alpha / 2)))

scipy-stats-intro.solution:
r"""Reference solution for ST-14 Introducing scipy.stats.

The frozen distribution holds the parameters, so every fact is one method call. Only the density
method differs between continuous (`pdf`) and discrete (`pmf`) families. Validation happens before
SciPy is called, because SciPy returns `nan` for invalid parameters instead of raising.
"""
from scipy import stats


def distribution_facts(kind, params, x, q):
    if not 0 < q < 1:
        raise ValueError("q must be strictly between 0 and 1")
    if kind == "norm":
        mu, sigma = params
        if sigma <= 0:
            raise ValueError("sigma must be positive")
        dist = stats.norm(loc=mu, scale=sigma)
        density = dist.pdf(x)
    elif kind == "binom":
        n, p = params
        if n < 0 or not 0 <= p <= 1:
            raise ValueError("need n >= 0 and 0 <= p <= 1")
        dist = stats.binom(n, p)
        density = dist.pmf(x)
    else:
        raise ValueError("kind must be 'norm' or 'binom'")
    return {"density": float(density), "cdf": float(dist.cdf(x)), "quantile": float(dist.ppf(q)),
            "mean": float(dist.mean()), "std": float(dist.std())}

chi-square-scipy.solution:
r"""Reference solution for ST-15 Chi-Square Test with SciPy.

SciPy needs expected counts, so the probabilities are scaled by the total. `chisquare` returns the
statistic and the upper-tail probability under the chi-square distribution with k − 1 degrees of
freedom; comparing that p-value with α replaces the table lookup of a critical value.
"""
from scipy import stats


def chi_square_test(observed, probs, alpha=0.05):
    if not 0 < alpha < 1:
        raise ValueError("alpha must be between 0 and 1")
    if len(observed) != len(probs) or len(observed) < 2:
        raise ValueError("need matching observed and probs with at least two categories")
    if any(p <= 0 for p in probs) or abs(sum(probs) - 1) > 1e-9:
        raise ValueError("probs must be positive and sum to 1")
    if any(o < 0 for o in observed):
        raise ValueError("counts must be non-negative")
    total = sum(observed)
    if total == 0:
        raise ValueError("total count is zero")
    expected = [total * p for p in probs]
    result = stats.chisquare(observed, f_exp=expected)
    p_value = float(result.pvalue)
    return {"statistic": float(result.statistic), "p_value": p_value,
            "df": len(observed) - 1, "reject": p_value < alpha}

