nlp-error-analysis.statement:
## Task

Write `error_report(texts, y_true, y_pred, labels)` returning

* `"confusion"`: `confusion_matrix(y_true, y_pred, labels=labels)` as a list of int lists;
* `"per_class"`: `{label: {"precision": float, "recall": float, "f1": float, "support": int}}` from
  `classification_report(..., labels=labels, output_dict=True, zero_division=0)`;
* `"macro_f1"`: the report's `"macro avg"` F1 as a float;
* `"errors"`: `(text, true_label, predicted_label)` tuples for every misclassified example, in input order.

Raise `ValueError` if the three sequences differ in length.

nlp-error-analysis.solution:
r"""Reference solution for NL-16 Evaluating Text Classifiers.

The confusion matrix and the report come straight from `sklearn.metrics` with a fixed label order,
so rows, columns and per-class entries line up. Collecting the misclassified texts beside their true
and predicted labels gives the material for error analysis.
"""
from sklearn.metrics import classification_report, confusion_matrix


def error_report(texts, y_true, y_pred, labels):
    if not len(texts) == len(y_true) == len(y_pred):
        raise ValueError("texts, y_true and y_pred must have the same length")
    report = classification_report(y_true, y_pred, labels=labels, output_dict=True, zero_division=0)
    per_class = {}
    for label in labels:
        row = report[str(label)]
        per_class[label] = {"precision": float(row["precision"]), "recall": float(row["recall"]),
                            "f1": float(row["f1-score"]), "support": int(row["support"])}
    return {"confusion": confusion_matrix(y_true, y_pred, labels=labels).tolist(),
            "per_class": per_class, "macro_f1": float(report["macro avg"]["f1-score"]),
            "errors": [(t, a, b) for t, a, b in zip(texts, y_true, y_pred) if a != b]}

ppmi-matrix.solution:
r"""Reference solution for NL-17 PPMI Co-occurrence Matrix.

Counting walks a symmetric window inside each sentence, skipping the centre and out-of-vocabulary
tokens (which still keep their positions). PPMI converts counts to joint and marginal probabilities
and takes log2 only where counts are positive, clipping negatives to zero.
"""
import numpy as np


def cooccurrence(sentences, vocab, window=2):
    if window < 1:
        raise ValueError("window must be >= 1")
    V = len(vocab)
    C = np.zeros((V, V), dtype=int)
    for s in sentences:
        for i, w in enumerate(s):
            if w not in vocab:
                continue
            for j in range(max(0, i - window), min(len(s), i + window + 1)):
                if j != i and s[j] in vocab:
                    C[vocab[w], vocab[s[j]]] += 1
    return C


def ppmi(C):
    C = np.asarray(C, dtype=float)
    N = C.sum()
    if N == 0:
        raise ValueError("empty co-occurrence matrix")
    P = C / N
    pw = P.sum(axis=1, keepdims=True)
    pc = P.sum(axis=0, keepdims=True)
    denom = pw * pc
    pmi = np.zeros_like(P)
    mask = C > 0
    np.log2(P / np.where(denom > 0, denom, 1.0), out=pmi, where=mask)
    return np.maximum(pmi, 0.0)

embedding-analogy.solution:
r"""Reference solution for NL-18 Word Embedding Analogies.

A shared ranking helper scores candidates by cosine with a target vector, excluding given words,
and sorts by score then name. Similarity search uses the word's own vector; analogies use the
3CosAdd offset vector.
"""
import numpy as np


def _cos(u, v):
    nu, nv = np.linalg.norm(u), np.linalg.norm(v)
    if nu == 0 or nv == 0:
        return 0.0
    return float(u @ v / (nu * nv))


def _rank(target, emb, exclude):
    scored = [(w, _cos(target, v)) for w, v in emb.items() if w not in exclude]
    return sorted(scored, key=lambda t: (-t[1], t[0]))


def most_similar(word, emb, k=3):
    if word not in emb:
        raise KeyError(word)
    return _rank(emb[word], emb, {word})[:k]


def analogy(a, b, c, emb):
    for w in (a, b, c):
        if w not in emb:
            raise KeyError(w)
    ranked = _rank(emb[b] - emb[a] + emb[c], emb, {a, b, c})
    if not ranked:
        raise ValueError("no candidate words")
    return ranked[0][0]

